import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildSchema, isAbstractType, isObjectType } from 'graphql';

const workspaceDir = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '..'
);
const schemaFile = path.join(workspaceDir, 'schema.shopana.graphql');
const generatedDir = path.join(
  workspaceDir,
  'packages/shopana-storefront-sdk/src/graphql/apollo/generated'
);
const header =
  '// Generated by scripts/codegen-possible-types.mjs from schema.shopana.graphql. Do not edit.\n';

const schema = buildSchema(await readFile(schemaFile, 'utf8'));
const types = Object.values(schema.getTypeMap()).filter(
  (type) => !type.name.startsWith('__')
);

// Apollo matches fragments on interfaces and unions (`... on Media`) only with possibleTypes.
const possibleTypes = Object.fromEntries(
  types
    .filter((type) => isAbstractType(type))
    .map((type) => [
      type.name,
      schema
        .getPossibleTypes(type)
        .map(({ name }) => name)
        .sort(),
    ])
    .sort(([left], [right]) => left.localeCompare(right))
);

// An object written without an id (its type has none, or the query does not select it) is
// stored inside its parent; the cache merges what each query writes there instead of
// replacing it (see createApolloCache).
const rootTypes = new Set(
  [
    schema.getQueryType(),
    schema.getMutationType(),
    schema.getSubscriptionType(),
  ].filter(Boolean)
);
const objectTypes = types
  .filter((type) => isObjectType(type) && !rootTypes.has(type))
  .map(({ name }) => name)
  .sort();

await writeFile(
  path.join(generatedDir, 'possibleTypes.ts'),
  header +
    `export const possibleTypes: Record<string, readonly string[]> = ${JSON.stringify(possibleTypes, null, 2)};\n`
);
await writeFile(
  path.join(generatedDir, 'objectTypes.ts'),
  header +
    `export const objectTypes: readonly string[] = ${JSON.stringify(objectTypes, null, 2)};\n`
);
